// Tormenta20 1.6.5 ItemT20 methods, copied verbatim from tormenta20.mjs: #_preCreate (T20:8266-8298),
// #_onUpdate (T20:8301-8329) and #_onDelete (T20:8334-8358). Joined into a class body with new Function.
export const PRE_CREATE = [
  "async _preCreate(data, options, user) {",
  "\tawait super._preCreate(data, options, user);",
  "\tif (!this.isEmbedded || this.parent.type === \"vehicle\") return;",
  "\tconst actorData = this.parent.system;",
  "\tconst isNPC = this.parent.type === \"npc\";",
  "\tlet updates = {};",
  "\tif (!isNPC || !options.statblockParsing) {",
  "\t\tswitch (data.type) {",
  "\t\t\tcase \"classe\":",
  "\t\t\t\t/* TODO */",
  "\t\t\t\tbreak;",
  "\t\t\tcase \"equipamento\":",
  "\t\t\t\tupdates = this._onCreateOwnedEquipment(data, actorData, isNPC);",
  "\t\t\t\tbreak;",
  "\t\t\tcase \"arma\":",
  "\t\t\t\tupdates = this._onCreateOwnedWeapon(data, actorData, isNPC);",
  "\t\t\t\tbreak;",
  "\t\t\tcase \"magia\":",
  "\t\t\t\tupdates = this._onCreateOwnedSpell(data, actorData, isNPC);",
  "\t\t\t\tbreak;",
  "\t\t\tcase \"poder\":",
  "\t\t\t\tupdates = this._onCreateOwnedPower(data, actorData, isNPC);",
  "\t\t\t\tbreak;",
  "\t\t\tcase \"race\":",
  "\t\t\t\tupdates = await this._onCreateOwnedRace(data, actorData, isNPC);",
  "\t\t\t\tbreak;",
  "\t\t}",
  "\t}",
  "\tupdates[\"flags.tormenta20.-=favorito\"] = null;",
  "\tif (updates) return this.updateSource(updates);",
  "}",
  "",
  "/* -------------------------------------------- */"
].join("\n");

export const ON_UPDATE = [
  "_onUpdate(changed, options, userId) {",
  "\tsuper._onUpdate(changed, options, userId);",
  "\tif (game.userId !== userId) return;",
  "\t// Set Initial Class",
  "\tif (this.parent && this.type === \"classe\") {",
  "\t\tif (foundry.utils.hasProperty(changed.system, \"inicial\")) {",
  "\t\t\tconst classes = this.actor.items.filter((i) => i.type === \"classe\" && i.id != this.id);",
  "\t\t\tlet updateItems;",
  "\t\t\t// When set as initial, unset other classes",
  "\t\t\tif (changed.system.inicial) {",
  "\t\t\t\tupdateItems = classes.map((i) => {",
  "\t\t\t\t\treturn { _id: i.id, \"system.inicial\": false };",
  "\t\t\t\t});",
  "\t\t\t}",
  "\t\t\t// If unseted initial, find first class and set it as initial",
  "\t\t\telse if (this.actor.items.find((i) => i.type === \"classe\" && !i.system.inicial)) {",
  "\t\t\t\tlet newInicial = this.actor.items.find((i) => i.type === \"classe\" && i.id != this.id);",
  "\t\t\t\tupdateItems = [{ _id: newInicial.id, \"system.inicial\": true }];",
  "\t\t\t}",
  "\t\t\tif (updateItems) this.actor.updateEmbeddedDocuments(\"Item\", updateItems);",
  "\t\t}",
  "\t\tif (foundry.utils.hasProperty(changed.system, \"niveis\")) {",
  "\t\t\tthis.actor.update({",
  "\t\t\t\t\"system.attributes.nivel.value\": this.actor.nivel",
  "\t\t\t});",
  "\t\t}",
  "\t}",
  "\tif (this.actor && game.userId === userId) this.actor._checkEncumbered();",
  "}"
].join("\n");

export const ON_DELETE = [
  "_onDelete(options, userId) {",
  "\tsuper._onDelete(options, userId);",
  "\tif (game.userId !== userId) return;",
  "\t// Assign a new primary class",
  "\tif (this.parent) {",
  "\t\tif (this.type === \"classe\") {",
  "\t\t\tif (this.actor.items.find((i) => i.type === \"classe\" && !i.system.inicial)) {",
  "\t\t\t\tlet newInicial = this.actor.items.find((i) => i.type === \"classe\");",
  "\t\t\t\tconst updateItems = [{ _id: newInicial.id, \"system.inicial\": true }];",
  "\t\t\t\tif (updateItems) this.actor.updateEmbeddedDocuments(\"Item\", updateItems);",
  "\t\t\t}",
  "\t\t\tthis.actor.update({",
  "\t\t\t\t\"system.attributes.nivel.value\": this.actor.nivel",
  "\t\t\t});",
  "\t\t} else if (this.type === \"race\") {",
  "\t\t\tconst grantedItems = this.getFlag(\"tormenta20\", \"grantedItems\") ?? [];",
  "\t\t\tconst updates = Object.fromEntries(",
  "\t\t\t\tObject.keys(this.system.atributos).map((key) => [`system.atributos.${key}.racial`, 0])",
  "\t\t\t);",
  "\t\t\tthis.actor.update(updates);",
  "\t\t\tconst granted = [...new Set(grantedItems.filter((grant) => this.parent?.items.has(grant)))];",
  "\t\t\tthis.parent.deleteEmbeddedDocuments(\"Item\", granted);",
  "\t\t}",
  "\t}",
  "}"
].join("\n");
